<?php
session(); include('../include/config.php'); require_once __DIR__.'/module_bootstrap.php'; hms_module_require_roles(array('admin','kasir'));
if($_SERVER['REQUEST_METHOD']==='POST'){hms_module_csrf();$action=$_POST['action']??'';
 if($action==='bill'){ $pid=(int)($_POST['patient_id']??0);$visit=(int)($_POST['visit_id']??0);$adm=(int)($_POST['admission_id']??0);$payer=$_POST['payer_type']??'TUNAI';$payerName=trim($_POST['payer_name']??'');$desc=trim($_POST['description']??'');$service=trim($_POST['service_type']??'LAINNYA');$qty=(float)($_POST['qty']??0);$price=(float)($_POST['unit_price']??0);if($qty<=0||$price<0||$pid<=0){hms_set_flash('danger','Data invoice tidak valid.');}else{ $total=round($qty*$price,2);$code=hms_module_next_code($con,'hms_bills','INV','id');mysqli_begin_transaction($con);try{$st=mysqli_prepare($con,'INSERT INTO hms_bills(patient_id,visit_id,admission_id,invoice_no,payer_type,payer_name,subtotal,total) VALUES(?,?,?,?,?,?,?,?)');mysqli_stmt_bind_param($st,'iiisssdd',$pid,$visit?:null,$adm?:null,$code,$payer,$payerName,$total,$total);if(!mysqli_stmt_execute($st))throw new RuntimeException('Invoice gagal dibuat.');$bid=mysqli_insert_id($con);mysqli_stmt_close($st);$st=mysqli_prepare($con,'INSERT INTO hms_bill_items(bill_id,service_type,description,qty,unit_price,amount) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($st,'issddd',$bid,$service,$desc,$qty,$price,$total);if(!mysqli_stmt_execute($st))throw new RuntimeException('Item invoice gagal dibuat.');mysqli_stmt_close($st);mysqli_commit($con);hms_module_audit($con,'CREATE','BILLING','hms_bills',$bid,'Invoice dibuat',null,array('patient_id'=>$pid,'invoice_no'=>$code,'total'=>$total,'payer_type'=>$payer));hms_set_flash('success','Invoice dibuat: '.$code);}catch(Throwable $e){mysqli_rollback($con);hms_set_flash('danger',$e->getMessage());}}}
 if($action==='pay'){ $bid=(int)($_POST['bill_id']??0);$amount=(float)($_POST['amount']??0);$method=$_POST['method']??'TUNAI';$ref=trim($_POST['reference_no']??'');if($bid<=0||$amount<=0){hms_set_flash('danger','Nominal pembayaran tidak valid.');}else{mysqli_begin_transaction($con);try{$bill=hms_fetch_one($con,'SELECT * FROM hms_bills WHERE id=? FOR UPDATE','i',array($bid));if(!$bill||$bill['status']==='BATAL')throw new RuntimeException('Invoice tidak dapat dibayar.');$paid=(float)hms_scalar($con,'SELECT COALESCE(SUM(amount),0) FROM hms_payments WHERE bill_id=?','i',array($bid));$remaining=round((float)$bill['total']-$paid,2);if($amount>$remaining+0.0001)throw new RuntimeException('Pembayaran melebihi sisa tagihan Rp '.number_format($remaining,2,',','.'));$st=mysqli_prepare($con,'INSERT INTO hms_payments(bill_id,amount,method,reference_no) VALUES(?,?,?,?)');mysqli_stmt_bind_param($st,'idss',$bid,$amount,$method,$ref);if(!mysqli_stmt_execute($st))throw new RuntimeException('Pembayaran gagal disimpan.');mysqli_stmt_close($st);$newPaid=$paid+$amount;$status=$newPaid+0.0001 >= (float)$bill['total']?'LUNAS':'SEBAGIAN';hms_execute($con,'UPDATE hms_bills SET status=? WHERE id=?','si',array($status,$bid));mysqli_commit($con);hms_module_audit($con,'PAYMENT','BILLING','hms_bills',$bid,'Pembayaran dicatat',array('paid'=>$paid,'status'=>$bill['status']),array('payment'=>$amount,'paid'=>$newPaid,'status'=>$status,'method'=>$method));hms_set_flash('success','Pembayaran dicatat.');}catch(Throwable $e){mysqli_rollback($con);hms_set_flash('danger',$e->getMessage());}}}
}
$patients=hms_fetch_all($con,'SELECT ID,PatientName FROM tblpatient ORDER BY PatientName LIMIT 500');$visits=hms_fetch_all($con,"SELECT id,registration_no,patient_id,visit_type,visit_date FROM hms_patient_visits ORDER BY id DESC LIMIT 300");$admissions=hms_fetch_all($con,"SELECT id,admission_no,patient_id,status FROM hms_admissions ORDER BY id DESC LIMIT 300");$charges=hms_fetch_all($con,"SELECT c.*,p.PatientName,b.invoice_no FROM hms_clinical_charges c LEFT JOIN tblpatient p ON p.ID=c.patient_id LEFT JOIN hms_bills b ON b.id=c.bill_id ORDER BY c.id DESC LIMIT 100");$bills=hms_fetch_all($con,"SELECT b.*,p.PatientName,COALESCE((SELECT SUM(amount) FROM hms_payments py WHERE py.bill_id=b.id),0) paid FROM hms_bills b LEFT JOIN tblpatient p ON p.ID=b.patient_id ORDER BY b.id DESC LIMIT 100");$role=hms_module_current_role();hms_layout_header('Kasir & Billing',$role,'operations');
?>
<div class="hms-page-title"><div><h1>Kasir & Billing</h1><div class="text-muted">Invoice layanan, penjamin dan pembayaran.</div></div></div>
<div class="row g-3 mb-4"><div class="col-lg-7"><div class="hms-card p-3"><h2 class="h5">Buat Invoice</h2><form method="post" class="row g-2"><?php echo hms_csrf_field(); ?><input type="hidden" name="action" value="bill"><div class="col-md-5"><select name="patient_id" class="form-select" required><option value="">Pasien</option><?php foreach($patients as $p){ ?><option value="<?php echo (int)$p['ID']; ?>"><?php echo hms_e($p['PatientName']); ?></option><?php } ?></select></div><div class="col-md-3"><select name="visit_id" class="form-select"><option value="0">Kunjungan</option><?php foreach($visits as $v){ ?><option value="<?php echo (int)$v['id']; ?>"><?php echo hms_e($v['registration_no'].' / '.$v['visit_type']); ?></option><?php } ?></select></div><div class="col-md-3"><select name="admission_id" class="form-select"><option value="0">Admission</option><?php foreach($admissions as $a){ if($a['status']==='DIRAWAT'){ ?><option value="<?php echo (int)$a['id']; ?>"><?php echo hms_e($a['admission_no']); ?></option><?php }} ?></select></div><div class="col-md-3"><select name="payer_type" class="form-select"><option>TUNAI</option><option>BPJS</option><option>ASURANSI</option><option>PERUSAHAAN</option></select></div><div class="col-md-4"><input name="payer_name" class="form-control" placeholder="Nama penjamin"></div><div class="col-md-4"><input name="service_type" class="form-control" placeholder="Jenis layanan" required></div><div class="col-md-4"><input name="description" class="form-control" placeholder="Deskripsi" required></div><div class="col-md-2"><input name="qty" type="number" min="0.01" step="0.01" value="1" class="form-control"></div><div class="col-md-2"><input name="unit_price" type="number" min="0" step="0.01" class="form-control" placeholder="Tarif" required></div><div class="col-12"><button class="btn btn-primary">Buat Invoice</button></div></form></div></div>
<div class="col-lg-5"><div class="hms-card p-3"><h2 class="h5">Catat Pembayaran</h2><form method="post" class="row g-2"><?php echo hms_csrf_field(); ?><input type="hidden" name="action" value="pay"><div class="col-12"><select name="bill_id" class="form-select" required><option value="">Pilih invoice</option><?php foreach($bills as $b){ if($b['status']!=='LUNAS'&&$b['status']!=='BATAL'){ $remaining=max(0,(float)$b['total']-(float)$b['paid']); ?><option value="<?php echo (int)$b['id']; ?>"><?php echo hms_e($b['invoice_no'].' - '.$b['PatientName'].' - Sisa Rp '.number_format($remaining,0,',','.')); ?></option><?php }} ?></select></div><div class="col-6"><input name="amount" type="number" min="0.01" step="0.01" class="form-control" placeholder="Nominal" required></div><div class="col-6"><select name="method" class="form-select"><option>TUNAI</option><option>TRANSFER</option><option>KARTU</option><option>BPJS</option><option>ASURANSI</option><option>PERUSAHAAN</option></select></div><div class="col-12"><input name="reference_no" class="form-control" placeholder="No referensi"></div><div class="col-12"><button class="btn btn-success">Simpan Pembayaran</button></div></form></div></div></div>
<div class="hms-card p-3 mb-4"><h2 class="h5">Charge Klinis Terintegrasi</h2><div class="table-responsive"><table class="table"><thead><tr><th>Waktu</th><th>Pasien</th><th>Layanan</th><th>Jumlah</th><th>Invoice</th><th>Status</th></tr></thead><tbody><?php foreach($charges as $c){ ?><tr><td><?php echo hms_e($c['created_at']); ?></td><td><?php echo hms_e($c['PatientName']); ?></td><td><?php echo hms_e($c['description']); ?></td><td>Rp <?php echo number_format($c['amount'],0,',','.'); ?></td><td><?php echo hms_e($c['invoice_no']??'-'); ?></td><td><?php echo hms_status_badge($c['status']); ?></td></tr><?php } ?></tbody></table></div></div>
<div class="hms-card p-3"><h2 class="h5">Daftar Invoice</h2><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Pasien</th><th>Penjamin</th><th>Total</th><th>Dibayar</th><th>Status</th></tr></thead><tbody><?php foreach($bills as $b){ ?><tr><td><?php echo hms_e($b['invoice_no']); ?></td><td><?php echo hms_e($b['PatientName']); ?></td><td><?php echo hms_e($b['payer_type'].' '.$b['payer_name']); ?></td><td>Rp <?php echo number_format($b['total'],0,',','.'); ?></td><td>Rp <?php echo number_format($b['paid'],0,',','.'); ?></td><td><?php echo hms_status_badge($b['status']); ?></td></tr><?php } ?></tbody></table></div></div>
<?php hms_layout_footer(); ?>
